def _symmetries(shape):
    pts = list(shape)
    result = set()
    for flip in (1, -1):
        for rot in range(4):
            vals = []
            for y, x in pts:
                x *= flip
                for _ in range(rot):
                    y, x = x, -y
                vals.append((y, x))
            y0 = min(y for y, x in vals)
            x0 = min(x for y, x in vals)
            result.add(frozenset((y-y0, x-x0) for y, x in vals))
    return result

def transform(grid):
    out = [row[:] for row in grid]
    comps = _components(grid)
    big6 = [set(cells) for color, cells in comps if color == 6 and len(cells) > 10]
    for color, cells in comps:
        if color != 1 or len(cells) != 3:
            continue
        shape = _norm(cells)
        if len({r for r,c in cells}) != 2 or len({c for r,c in cells}) != 2:
            continue
        syms = _symmetries(shape)
        for big in big6:
            matched = False
            for y, x in big:
                for candidate in syms:
                    if all((y+dy, x+dx) in big for dy,dx in candidate):
                        matched = True
                        break
                if matched:
                    break
            if matched:
                for r,c in cells:
                    out[r][c] = 6
                break
    return out
